import gc, io
class W(io.TextIOWrapper):
 def close(self):
  if self.buffer is not None:
   try: self.flush()
   finally: self.detach()

b=io.BytesIO(); w=W(b, encoding='utf8'); w.write('x'); w.close()
print('buffer', b.closed, b.getvalue())
for attr in ('closed','buffer'):
 try: print(attr,getattr(w,attr))
 except Exception as e: print(attr,type(e).__name__,e)
try: w.close(); print('second close ok')
except Exception as e: print('second close',type(e).__name__,e)

class W2(io.TextIOWrapper):
 def close(self):
  try: buffer=self.buffer
  except ValueError: return
  try: self.flush()
  finally: self.detach()

b2=io.BytesIO(); w2=W2(b2); w2.write('y'); w2.close(); w2.close(); print('W2',b2.getvalue())
